def project_approved_passport_table(passport: DrawingPassport) -> ApprovedPassportTableProjection:
    """Build the stable geometry-table projection from DrawingPassport v2."""
    dimensions = {dimension.id: dimension for dimension in passport.dimensions}
    features = {feature.id: feature for feature in passport.features}
    features_by_dimension: dict[str, list[Feature]] = {}
    for feature in passport.features:
        for dimension_id in feature.dimension_refs:
            features_by_dimension.setdefault(dimension_id, []).append(feature)
    relations_by_dimension: dict[str, list[GeometryRelation]] = {}
    inner_dimension_refs = {
        relation.inner_dimension_ref
        for relation in passport.geometry_relations
        if isinstance(relation, StockSectionRelation)
        and relation.inner_dimension_ref is not None
        and all(e.recognition_status == "observed" for e in relation.evidence_refs)
    }
    uncertain_inner_refs = {
        relation.inner_dimension_ref
        for relation in passport.geometry_relations
        if isinstance(relation, StockSectionRelation)
        and relation.inner_dimension_ref is not None
        and any(e.recognition_status != "observed" for e in relation.evidence_refs)
    }
    for relation in passport.geometry_relations:
        for dimension_id in relation.dimension_refs:
            relations_by_dimension.setdefault(dimension_id, []).append(relation)

    rows = []
    for dimension in passport.dimensions:
        relations = relations_by_dimension.get(dimension.id, [])
        member_features = features_by_dimension.get(dimension.id, [])
        feature_related_ids = [
            related_id
            for feature in member_features
            for related_id in feature.dimension_refs
            if related_id != dimension.id
        ]
        relation_related_ids = [
            related_id
            for relation in relations
            for related_id in relation.dimension_refs
            if related_id != dimension.id
        ]
        relation_feature_ids = [
            feature_id for relation in relations for feature_id in relation.feature_refs
        ]
        feature_ids = list(
            dict.fromkeys(
                [
                    *([dimension.feature_id] if dimension.feature_id else []),
                    *(feature.id for feature in member_features),
                    *relation_feature_ids,
                ]
            )
        )
        related_ids = list(dict.fromkeys([*feature_related_ids, *relation_related_ids]))
        related_dimensions = [dimensions[related_id] for related_id in related_ids]
        roughness = [
            value
            for value in passport.roughness.local
            if (dimension.feature_id is not None and value.feature_ref == dimension.feature_id)
            or (value.target_description == dimension.id)
            or (value.feature_ref == dimension.id)
        ]
        if not roughness and passport.roughness.general is not None:
            roughness = [passport.roughness.general]
        evidence_refs = [dimension.evidence]
        evidence_refs.extend(
            features[feature_id].evidence for feature_id in feature_ids if feature_id in features
        )
        evidence_refs.extend(
            evidence for relation in relations for evidence in relation.evidence_refs
        )
        evidence_refs.extend(value.evidence for value in roughness)
        label = (
            _HOLE_DIAMETER_LABEL
            if _is_hole_diameter(dimension, features)
            or (dimension.kind == DimensionKind.DIAMETER and dimension.id in inner_dimension_refs)
            else _KIND_LABELS[dimension.kind]
        )
        if dimension.kind == DimensionKind.DIAMETER and dimension.id in uncertain_inner_refs:
            label = "Диаметр (принадлежность не подтверждена)"
        if dimension.kind == DimensionKind.DIAMETER and any(
            feature.kind == FeatureKind.THREAD
            and (
                not isinstance(feature.typed_parameters, ThreadParameters)
                or feature.typed_parameters.internal_external not in {"internal", "external"}
            )
            for feature in member_features
        ):
            label = "Диаметр резьбы (принадлежность не подтверждена)"
        relation_descriptions = [
            relation.description.strip()
            for relation in relations
            if relation.description and relation.description.strip()
        ]
        if related_dimensions:
            related_display = ", ".join(
                _dimension_display(item, include_tolerance=True) for item in related_dimensions
            )
        elif relation_descriptions:
            related_display = "; ".join(relation_descriptions)
        else:
            related_display = "-"
        role_hint = _extract_dimension_role_hint(dimension, relations, member_features)
        ui_label = f"{label} ({role_hint})" if role_hint else label
        rows.append(
            ApprovedPassportTableRow(
                row_id=f"dimension:{dimension.id}",
                element_kind_label=label,
                element_role_hint=role_hint,
                ui_element_kind_label=ui_label,
                size_display=_dimension_display(dimension),
                tolerance_display=_tolerance_display(
                    dimension,
                    reference_confirmed=reference_mark_confirmed(
                        dimension, passport.technical_requirements
                    ),
                ),
                roughness_display=_roughness_display(roughness),
                related_dimensions_display=related_display,
                dimension_refs=[dimension.id],
                feature_refs=feature_ids,
                relation_refs=[relation.id for relation in relations],
                evidence_refs=list(dict.fromkeys(evidence_refs)),
                effective_limits_display=_effective_limits_display(dimension),
                target_median_display=_target_median_display(dimension),
