from __future__ import annotations

import json

from pydantic import BaseModel, ConfigDict

from metall_mvp.domain.passport.models import DrawingPassport, VerificationStatus
from metall_mvp.runtime.models import SpanKind, TriggerType
from metall_mvp.runtime.service import TraceRuntime
from metall_mvp.workflows.recognition import validate_passport_provenance


class OperatorRevisionResult(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    run_id: str
    parent_run_id: str
    source_passport_artifact_id: str
    revision_artifact_id: str
    passport: DrawingPassport
    operator: str
    reason: str


def _has_operator_review(passport: DrawingPassport) -> bool:
    payload = passport.model_dump(mode="json")

    def visit(item: object) -> bool:
        if isinstance(item, dict):
            if "verification_status" in item:
                return item["verification_status"] in {
                    VerificationStatus.OPERATOR_CONFIRMED.value,
                    VerificationStatus.OPERATOR_CORRECTED.value,
                }
            return any(visit(child) for child in item.values())
        if isinstance(item, list):
            return any(visit(child) for child in item)
        return False

    return visit(payload)


async def save_operator_revision(
    runtime: TraceRuntime,
    *,
    parent_run_id: str,
    passport: DrawingPassport,
    operator: str,
    reason: str,
) -> OperatorRevisionResult:
    if not operator.strip():
        raise ValueError("operator revision requires an operator")
    if not reason.strip():
        raise ValueError("operator revision requires a reason")
    parent = runtime.repository.get_run(parent_run_id)
    machine_artifacts = [
        artifact
        for artifact in runtime.repository.list_artifacts(parent_run_id)
        if artifact.kind == "normalized_machine_passport"
    ]
    if not machine_artifacts:
        raise ValueError("parent run has no normalized machine passport")
    source_artifact = machine_artifacts[-1]
    machine_passport = DrawingPassport.model_validate_json(runtime.artifacts.read(source_artifact))
    if passport.passport_id != machine_passport.passport_id:
        raise ValueError("operator revision passport_id does not match machine passport")
    if passport.document_id != machine_passport.document_id:
        raise ValueError("operator revision document_id does not match machine passport")
    if passport.schema_version != machine_passport.schema_version:
        raise ValueError("operator revision schema_version does not match machine passport")
    if passport.page_no != machine_passport.page_no:
        raise ValueError("operator revision page_no does not match machine passport")

    latest_revision = machine_passport.revision
    for candidate_run in runtime.repository.list_runs(project_id=parent.project_id, limit=500):
        if candidate_run.parent_run_id != parent_run_id:
            continue
        for candidate_artifact in runtime.repository.list_artifacts(candidate_run.id):
            if candidate_artifact.kind != "operator_passport_revision":
                continue
            candidate_passport = DrawingPassport.model_validate_json(
                runtime.artifacts.read(candidate_artifact)
            )
            latest_revision = max(latest_revision, candidate_passport.revision)
    if passport.revision != latest_revision + 1:
        raise ValueError(f"operator revision must be exactly {latest_revision + 1}")
    if not _has_operator_review(passport):
        raise ValueError("operator revision must confirm or correct at least one fact")

    region_ids = {"whole_page"}
    for artifact in runtime.repository.list_artifacts(parent_run_id):
        if artifact.kind != "regions":
            continue
        regions_payload = json.loads(runtime.artifacts.read(artifact))
        region_ids.update(
            region["id"]
            for region in regions_payload.get("regions", [])
            if isinstance(region, dict) and isinstance(region.get("id"), str)
        )
    validate_passport_provenance(
        passport,
        allowed_region_ids=region_ids,
        allowed_trace_span_ids={span.id for span in runtime.repository.list_spans(parent_run_id)},
    )

    run = runtime.create_run(
        project_id=parent.project_id,
        document_id=parent.document_id,
        parent_run_id=parent_run_id,
        trigger_type=TriggerType.OPERATOR_EDIT,
    )

